export default [{"id":"normal","name":{"en":"Normal sinus rhythm","zh":"正常窦性心律"},"hr":75,"patch":{},"note":{"en":"At75bpm, a coordinated atrial contraction precedes ventricular systole. Pressure crossovers close and open valves; LV volume remains constant during both isovolumetric phases. These curves are idealized teaching values.","zh":"75次/分时，协调的心房收缩先于心室收缩。压力差方向决定瓣膜开闭；两个等容期左室容积恒定。本曲线为理想化教学参数。"},"questions":[{"en":"Why does mitral closure precede aortic opening?","zh":"为什么二尖瓣关闭先于主动脉瓣开放？"},{"en":"Why is ventricular volume constant while pressure changes?","zh":"为什么压力变化时心室容积可保持恒定？"}]},{"id":"exercise","name":{"en":"Exercise / sympathetic drive","zh":"运动 / 交感兴奋"},"hr":150,"patch":{"contractility":1.35,"edv":128,"esv":40},"note":{"en":"Sympathetic activation increases heart rate and contractility. Diastole shortens more than systole, and diastasis disappears at150bpm. The Frank–Starling and sympathetic responses are represented as teaching parameter shifts.","zh":"交感兴奋增加心率和收缩性。舒张期缩短幅度大于收缩期，150次/分时减慢充盈期消失。Frank–Starling效应与交感反应以教学参数改变表示。"},"questions":[{"en":"Which phase disappears first as heart rate rises?","zh":"心率升高时哪一期首先消失？"},{"en":"How can cardiac output rise despite shorter filling time?","zh":"充盈时间缩短时心输出量为何仍可增加？"}]},{"id":"vagal","name":{"en":"Vagal / sinus bradycardia","zh":"迷走兴奋 / 窦性心动过缓"},"hr":45,"patch":{"prMs":180},"note":{"en":"Vagal drive slows SA discharge and AV conduction. Most additional cycle time appears during diastasis. This scenario illustrates sinus bradycardia, not a diagnosis or a treatment threshold.","zh":"迷走兴奋减慢窦房结放电和房室传导。延长的心动周期主要增加减慢充盈时间。本情景用于演示窦性心动过缓，不作为诊断或治疗阈值。"},"questions":[{"en":"Where is most of the longer RR interval spent?","zh":"RR间期延长的时间主要增加在哪一期？"},{"en":"What happens to the SA phase4 slope?","zh":"窦房结4期去极化斜率如何改变？"}]},{"id":"af","name":{"en":"Atrial fibrillation","zh":"心房颤动"},"hr":95,"patch":{"atrialFibrillation":true,"atrialKick":0,"edv":108,"rrSequence":[0.76,1.22,0.88,1.11,0.67,1.36,1.02,0.98]},"note":{"en":"There are no organized P waves or coordinated atrial kick. A fixed reproducible irregular RR sequence demonstrates variable filling time. Removing12mL of active filling reduces baseline stroke-volume replacement by17%; the clinical effect is patient and rate dependent.","zh":"无规则P波和协调的心房收缩。固定可复现的不规则RR序列展示充盈时间变化。失去12mL主动充盈使基线每搏补充量减少约17%；临床影响取决于个体及心率。"},"questions":[{"en":"Why is there no organized a wave?","zh":"为何没有规则a波？"},{"en":"Why does loss of atrial contraction matter more with a stiff ventricle?","zh":"心室顺应性降低时，失去心房收缩为何影响更大？"}]},{"id":"first-degree","name":{"en":"First-degree AV block","zh":"一度房室传导阻滞"},"hr":75,"patch":{"prMs":260},"note":{"en":"Each P wave still conducts to a QRS complex, but PR is260ms. The atrial timing shifts earlier relative to ventricular events; ventricular timing remains regular. This is an AV delay rather than AV dissociation.","zh":"每个P波仍下传产生QRS波，但PR延长至260ms。相对于心室事件，心房活动提前；心室节律仍规则。这是房室传导延迟。"},"questions":[{"en":"Is any ventricular beat dropped?","zh":"是否出现心室漏搏？"},{"en":"How does PR differ from QRS duration?","zh":"PR间期与QRS时限有何不同？"}]},{"id":"complete-block","name":{"en":"Complete AV block","zh":"三度房室传导阻滞"},"hr":40,"patch":{"completeBlock":true,"atrialHR":75,"prMs":null,"escapeQrsMs":140},"note":{"en":"Atria follow an independent75bpm sinus clock while a40bpm ventricular escape rhythm drives the mechanical cycle. P waves march through QRS complexes without a fixed PR; atrial contraction against closed AV valves can produce cannon a waves.","zh":"心房按独立75次/分窦性节律活动，心室以40次/分逸搏驱动机械周期。P波与QRS无固定PR关系；心房在房室瓣关闭时收缩可出现大炮a波。"},"questions":[{"en":"Can a single PR interval describe this rhythm?","zh":"能否用一个PR间期描述这种节律？"},{"en":"When can a cannon a wave appear?","zh":"大炮a波何时出现？"}]},{"id":"lbbb","name":{"en":"Left bundle branch block","zh":"左束支传导阻滞"},"hr":75,"patch":{"block":"left","branchDelayMs":70},"note":{"en":"Right-bundle activation is preserved, while left-ventricular activation is delayed through myocardium. The activation span expands to160ms and determines QRS width. Lead-II morphology is schematic; this is not a diagnostic12-lead ECG.","zh":"右束支激动保留，左室经心肌缓慢传播而延迟激动。激动跨度延长至160ms并决定QRS宽度。Ⅱ导联形态为示意，不能替代诊断性12导联心电图。"},"questions":[{"en":"Why is QRS wider?","zh":"QRS为何增宽？"},{"en":"Which ventricle contracts later?","zh":"哪个心室收缩较晚？"}]},{"id":"rbbb","name":{"en":"Right bundle branch block","zh":"右束支传导阻滞"},"hr":75,"patch":{"block":"right","branchDelayMs":60},"note":{"en":"Left-bundle activation is preserved and RV activation is delayed. The wider activation span determines a150ms QRS. Dyssynchrony is illustrated, with no claim to reconstruct diagnostic V1/V6 morphology.","zh":"左束支激动保留，右室激动延迟。激动跨度决定150ms的QRS。模型展示不同步，不重建具有诊断意义的V1/V6形态。"},"questions":[{"en":"Which activation pathway remains intact?","zh":"哪条传导通路仍完整？"},{"en":"Why does right-sided activation finish late?","zh":"右心激动为何较晚完成？"}]},{"id":"wpw","name":{"en":"WPW / ventricular pre-excitation","zh":"WPW / 心室预激"},"hr":75,"patch":{"accessoryPathway":true,"prMs":115,"accessoryAdvanceMs":45},"note":{"en":"An accessory AV connection activates ventricular myocardium before the normal His–Purkinje route. A short PR and slurred delta upstroke precede the ordinary rapid activation. The example illustrates pre-excitation, not re-entrant tachycardia.","zh":"房室旁路早于正常希氏束–浦肯野通路激动部分心室肌。短PR与起始缓慢的delta波出现在正常快速激动之前。此例演示预激，不模拟折返性心动过速。"},"questions":[{"en":"Why is the early QRS upstroke slurred?","zh":"QRS起始上升支为何缓慢？"},{"en":"Which normal delay is bypassed?","zh":"旁路绕过了哪一处正常延迟？"}]},{"id":"as","name":{"en":"Aortic stenosis","zh":"主动脉瓣狭窄"},"hr":75,"patch":{"stenosis":1,"lvSystolicBoost":65,"edv":130,"esv":60,"murmur":"ejection","s4":0.7},"note":{"en":"A narrowed aortic valve sustains a systolic LV-to-aortic pressure gradient and a crescendo–decrescendo murmur. The modeled LV generates extra pressure while forward flow encounters increased resistance. S4 illustrates reduced compliance when sinus rhythm is present.","zh":"狭窄主动脉瓣造成收缩期左室–主动脉压差及递增–递减型杂音。模型中左室产生更高压力，前向血流阻力增加。窦性心律下S4示意顺应性降低。"},"questions":[{"en":"Why can LV systolic pressure exceed aortic pressure markedly?","zh":"左室收缩压为何可明显高于主动脉压？"},{"en":"How does afterload alter the PV loop?","zh":"后负荷如何改变压力–容积环？"}]},{"id":"mr","name":{"en":"Mitral regurgitation","zh":"二尖瓣反流"},"hr":75,"patch":{"regurgitation":"mitral","regurgitantFraction":0.35,"edv":145,"esv":50,"giantV":20,"murmur":"holosystolic","s3":1},"note":{"en":"An incompetent mitral valve permits systolic reverse flow into the LA despite a closing pressure gradient. The LA v wave becomes large; S3 may accompany increased filling. Total LV stroke volume includes forward and regurgitant components, and true isovolumetric intervals are lost.","zh":"二尖瓣关闭不全时，即使压力差促使瓣膜关闭，收缩期仍可向左房反流。左房v波增大，充盈增加时可伴S3。左室总每搏量包括前向与反流部分，真正等容期消失。"},"questions":[{"en":"Why can a closed valve still leak?","zh":"瓣膜处于关闭状态为何仍可反流？"},{"en":"Is total LV stroke volume equal to forward stroke volume?","zh":"左室总每搏量是否等于前向每搏量？"}]},{"id":"hfref","name":{"en":"Heart failure with reduced EF","zh":"射血分数降低型心力衰竭"},"hr":75,"patch":{"edv":170,"esv":115,"contractility":0.65,"fillingPressure":8,"s3":1},"note":{"en":"Reduced contractility raises ESV and lowers EF to about32%. A dilated ventricle shifts the PV loop right and elevated filling pressure illustrates congestion. These values are one didactic phenotype, not universal features of every person with HFrEF.","zh":"收缩性降低使收缩末期容积增大，射血分数降至约32%。心室扩张使PV环右移，充盈压升高示意淤血。这些数值仅代表一种教学表型，并非所有患者的共同特征。"},"questions":[{"en":"Why can EDV be high while EF is low?","zh":"舒张末期容积增大时射血分数为何仍低？"},{"en":"Which PV relation reflects reduced contractility?","zh":"哪条压力–容积关系反映收缩性降低？"}]}];
